import {Game,CREW,STAGES,clamp} from './engine.mjs';
import {ArcadeAudio} from './audio.mjs';
const $=id=>document.getElementById(id),canvas=$('game'),ctx=canvas.getContext('2d',{alpha:false});
ctx.imageSmoothingEnabled=false;
const audio=new ArcadeAudio(),keys=new Set(),pressed=new Set(),images={},selected=[1,0];
let game=null,activePicker=0,ready=false,paused=false,lastTime=0,clock=0,highScore=0,overlayMode='',toast='',toastTime=0,previousPad=[],audioWanted=false;
try{highScore=Number(localStorage.getItem('mortal-sopranos-high-score')||0)||0;}catch{}
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)').matches;
const padNames=['TONY','CARMELA','ARTIE','JUNIOR'];
$('solo').disabled=$('coop').disabled=true;
function record(){ $('record').textContent='HI-SCORE '+Math.floor(highScore).toString().padStart(6,'0'); }
record();
function saveScore(){if(game&&game.score>highScore){highScore=game.score;try{localStorage.setItem('mortal-sopranos-high-score',String(highScore));}catch{}record();}}
async function loadAssets(){try{await Promise.all(['crew','rivals','locations'].map(name=>new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{images[name]=img;resolve();};img.onerror=()=>reject(new Error(name));img.src=`assets/${name}.png`;})));ready=true;$('solo').disabled=$('coop').disabled=false;$('loading').textContent='FREE PLAY · KEYBOARD / GAMEPAD · NO DOWNLOAD';buildRoster();}catch(e){$('loading').textContent=`Could not load ${e.message}. Reload to retry.`;}}
function buildRoster(){const root=$('roster');root.replaceChildren();CREW.forEach((c,i)=>{const button=document.createElement('button');button.className='fighter-card';button.setAttribute('aria-label',`${c.full}. ${c.weapon}. Special: ${c.special}`);button.dataset.index=i;const portrait=document.createElement('canvas');portrait.width=96;portrait.height=128;portrait.className='fighter-portrait';portrait.setAttribute('aria-hidden','true');const pc=portrait.getContext('2d');pc.imageSmoothingEnabled=false;if(images.crew)pc.drawImage(images.crew,90,i*256,192,256,0,0,96,128);const copy=document.createElement('div');copy.className='fighter-copy';copy.innerHTML=`<h3>${c.name}</h3><span class="role">${c.role}</span><p class="weapon">${i===1?'Vacuum cleaner':i===0?'Heavy hitter':i===2?'Frying pan':'Walking cane'}</p><span class="stats" aria-label="Power ${c.power} of 5">${Array.from({length:5},(_,j)=>`<i class="${j<c.power?'lit':''}"></i>`).join('')}</span>`;const badge=document.createElement('span');badge.className='p-badge';button.append(portrait,copy,badge);button.addEventListener('click',()=>{selected[activePicker]=i;updateSelection();audio.effect('select');});root.append(button);});updateSelection();}
function updateSelection(){document.querySelectorAll('.fighter-card').forEach((b,i)=>{b.classList.toggle('selected',selected[0]===i);b.classList.toggle('p2',selected[1]===i);b.setAttribute('aria-pressed',String(selected[activePicker]===i));b.querySelector('.p-badge').textContent=[selected[0]===i?'P1':'',selected[1]===i?'P2':''].filter(Boolean).join(' / ');});$('name1').textContent=CREW[selected[0]].name;$('name2').textContent=CREW[selected[1]].name;const c=CREW[selected[activePicker]];$('special-description').textContent=`SPECIAL / “${c.special}” — ${c.description}`;[0,1].forEach(i=>{$('pick'+(i+1)).classList.toggle('active',activePicker===i);$('pick'+(i+1)).setAttribute('aria-pressed',String(activePicker===i));});}
$('pick1').onclick=()=>{activePicker=0;updateSelection();};$('pick2').onclick=()=>{activePicker=1;updateSelection();};
async function start(players){if(!ready)return;game=new Game(selected.slice(0,players));paused=false;overlayMode='';keys.clear();pressed.clear();$('title-screen').classList.add('hidden');$('selection').classList.add('hidden');$('game-overlay').classList.add('hidden');$('play-toolbar').classList.remove('hidden');$('touch-controls').classList.remove('hidden');document.body.classList.add('playing');audio.music=true;audio.setStage(0);if(!audioWanted){audioWanted=true;try{await audio.start();}catch{}}else if(audio.enabled){await audio.ctx?.resume();}updateSound();canvas.focus();toast=STAGES[0].story;toastTime=5;}
$('solo').onclick=()=>start(1);$('coop').onclick=()=>start(2);
function setOverlay(mode,title,copy,button,kicker='FAMILY BUSINESS'){overlayMode=mode;$('overlay-title').textContent=title;$('overlay-copy').textContent=copy;$('overlay-kicker').textContent=kicker;$('resume').textContent=button;$('resume').classList.toggle('hidden',!button);$('game-overlay').classList.remove('hidden');$('resume').focus();audio.music=false;}
function pause(){if(!game||game.phase!=='playing')return;paused=!paused;keys.clear();pressed.clear();if(paused)setOverlay('pause','TAKE A BREATHER.','The neighborhood can wait. Your game is paused.','BACK TO BUSINESS','PAUSED');else{$('game-overlay').classList.add('hidden');overlayMode='';audio.music=true;canvas.focus();}}
$('pause').onclick=pause;
$('resume').onclick=()=>{if(overlayMode==='pause'){pause();return;}if(overlayMode==='stageclear'){game.startNextStage();audio.setStage(game.stage);toast=STAGES[game.stage].story;toastTime=5;}else if(overlayMode==='gameover'){if(!game.continueGame())return;}else if(overlayMode==='victory'){start(game.players.length);return;}$('game-overlay').classList.add('hidden');overlayMode='';audio.music=true;keys.clear();pressed.clear();canvas.focus();};
function returnToTitle(){saveScore();game=null;paused=false;overlayMode='';keys.clear();pressed.clear();$('game-overlay').classList.add('hidden');$('title-screen').classList.remove('hidden');$('selection').classList.remove('hidden');$('play-toolbar').classList.add('hidden');$('touch-controls').classList.add('hidden');document.body.classList.remove('playing');audio.music=true;audio.setStage(0);$('solo').focus();}
$('return').onclick=returnToTitle;
function showHelp(){if(game&&game.phase==='playing'&&!paused)pause();$('help-dialog').showModal();}
$('help').onclick=$('more-controls').onclick=showHelp;$('close-help').onclick=()=>$('help-dialog').close();$('help-dialog').addEventListener('click',e=>{if(e.target===$('help-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function updateSound(){$('sound').textContent=audio.enabled?'SOUND ON':'SOUND OFF';$('sound').setAttribute('aria-pressed',String(audio.enabled));$('sound').setAttribute('aria-label',audio.enabled?'Mute sound':'Enable sound');}
async function toggleSound(){audioWanted=true;if(audio.enabled)audio.mute();else{try{await audio.start();}catch{toast='Audio unavailable in this browser';toastTime=3;}}updateSound();}
$('sound').onclick=toggleSound;
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.querySelector('.cabinet').requestFullscreen();}catch{toast='Fullscreen is not available here. Open the game in your browser.';toastTime=5;}};
const gameplayKeys=new Set(['KeyW','KeyA','KeyS','KeyD','KeyF','KeyG','KeyH','KeyR','Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','KeyJ','KeyK','KeyL','KeyO','ShiftRight']);
addEventListener('keydown',e=>{if($('help-dialog').open)return;if(e.code==='Escape'&&!e.repeat){pause();e.preventDefault();return;}if(e.code==='KeyM'&&!e.repeat){toggleSound();return;}if(game&&gameplayKeys.has(e.code)){e.preventDefault();if(!keys.has(e.code))pressed.add(e.code);keys.add(e.code);}if(!game&&e.code==='Enter'&&e.target===document.body)start(1);});
addEventListener('keyup',e=>{keys.delete(e.code);});
addEventListener('blur',()=>{keys.clear();pressed.clear();if(game&&game.phase==='playing'&&!paused)pause();});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&game&&game.phase==='playing'&&!paused)pause();});
document.querySelectorAll('[data-key]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys.add(b.dataset.key);pressed.add(b.dataset.key);});for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,()=>{keys.delete(b.dataset.key);pressed.delete(b.dataset.key);});});
function inputs(){const held=k=>keys.has(k),tap=k=>pressed.has(k);const result=[{x:+held('KeyD')-held('KeyA'),y:+held('KeyS')-held('KeyW'),hit:held('KeyF'),kick:held('KeyG'),special:tap('KeyH'),jump:tap('Space'),block:held('KeyR')},{x:+held('ArrowRight')-held('ArrowLeft'),y:+held('ArrowDown')-held('ArrowUp'),hit:held('KeyJ'),kick:held('KeyK'),special:tap('KeyL'),jump:tap('ShiftRight'),block:held('KeyO')}];
 const pads=navigator.getGamepads?.()||[];let slot=0;for(const pad of pads){if(!pad||slot>1)continue;const p=result[slot],prev=previousPad[pad.index]||[],down=i=>!!pad.buttons[i]?.pressed,edge=i=>down(i)&&!prev[i];let x=Math.abs(pad.axes[0])>.2?pad.axes[0]:0,y=Math.abs(pad.axes[1])>.2?pad.axes[1]:0;x+=+down(15)-down(14);y+=+down(13)-down(12);p.x=clamp(p.x+x,-1,1);p.y=clamp(p.y+y,-1,1);p.hit||=down(2);p.kick||=down(1);p.jump||=edge(0);p.special||=edge(3);p.block||=down(4);if(edge(9)){if(!game)start(1);else pause();}previousPad[pad.index]=pad.buttons.map(b=>b.pressed);slot++;}pressed.clear();return result;
}
function rect(x,y,w,h,color){ctx.fillStyle=color;ctx.fillRect(Math.round(x),Math.round(y),w,h);}
function text(t,x,y,size=12,color='#f1e6c9',align='left',font='monospace'){ctx.fillStyle=color;ctx.font=`bold ${size}px ${font}`;ctx.textAlign=align;ctx.textBaseline='top';ctx.fillText(t,Math.round(x),Math.round(y));}
function backdrop(stage,camera=0){const top=['#3b3637','#091e27','#302a25'][stage];rect(0,0,960,540,top);if(images.locations){const width=1720,drawX=-300-camera*.16;ctx.drawImage(images.locations,0,stage*1024/3,1536,1024/3,drawX,20,width,382);if(drawX+width<960)ctx.drawImage(images.locations,0,stage*1024/3,1536,1024/3,drawX+width,20,width,382);}
 const grd=ctx.createLinearGradient(0,382,0,540);grd.addColorStop(0,stage===1?'#142329':'#343331');grd.addColorStop(1,'#141c1b');ctx.fillStyle=grd;ctx.fillRect(0,390,960,150);for(let i=0;i<95;i++){const x=((i*137.31-camera*.8)%1000+1000)%1000,y=393+(i*47.3)%150;rect(x,y,8+(i%4)*8,1,i%3===0?'#59605c32':'#060c0c44');}rect(0,397,960,2,'#8d89723b');for(let i=0;i<7;i++){let x=((i*180-camera)%1260+1260)%1260;rect(x,489,76,3,'#a59b6944');}const shade=ctx.createLinearGradient(0,0,0,130);shade.addColorStop(0,'#050908e6');shade.addColorStop(1,'#05090800');ctx.fillStyle=shade;ctx.fillRect(0,0,960,130);
 if(stage===1&&!reducedMotion){ctx.strokeStyle='#99bac126';ctx.lineWidth=1;ctx.beginPath();for(let i=0;i<60;i++){const x=(i*71+clock*53)%1000,y=(i*43+clock*330)%540;ctx.moveTo(x,y);ctx.lineTo(x-4,y+12);}ctx.stroke();}
}
function actor(entity,enemy=false,scale=1,camera=0){const x=Math.round(entity.x-camera),y=Math.round(entity.y),z=entity.z||0;if(x<-130||x>1080)return;const img=enemy?images.rivals:images.crew;if(!img)return;const dead=entity.hp<=0;let frame=0;if(entity.attack>0)frame=entity.attackKind==='kick'?3:2;else if(entity.moving)frame=Math.floor(clock*8)%2;if(entity.wind>0)frame=0;
 ctx.save();ctx.globalAlpha=dead?Math.min(1,entity.dead*2):.45;ctx.fillStyle='#030707';ctx.beginPath();ctx.ellipse(x,y+1,33*scale,8*scale,0,0,Math.PI*2);ctx.fill();ctx.restore();
 ctx.save();ctx.translate(x,y-z);ctx.scale(entity.face*scale,scale);if(dead){ctx.globalAlpha=Math.max(0,entity.dead);ctx.rotate(-1.4);ctx.translate(45,25);}else if(entity.stun>0)ctx.rotate(-.09);if(entity.invuln>0&&Math.floor(clock*18)%2===0)ctx.globalAlpha=.55;const bounce=entity.moving?Math.sin(clock*15)*2:Math.sin(clock*3+entity.crew)*1.2;if(entity.block){ctx.translate(-5,2);ctx.rotate(.06);}if(entity.spin>0)ctx.scale(Math.cos(clock*25)>.0?1:-1,1);ctx.drawImage(img,frame*384,entity.crew*256,384,256,-95,-144+bounce,216,144);ctx.restore();
 if(!enemy&&entity.hp>0&&entity.slot!==undefined){text('P'+(entity.slot+1),x,y+11,9,CREW[entity.crew].color,'center');if(entity.block){ctx.strokeStyle='#b7e0d1';ctx.lineWidth=2;ctx.beginPath();ctx.arc(x+entity.face*22,y-70-z,32,-1.5,1.5);ctx.stroke();}}
 if(enemy&&entity.hp>0){if(entity.wind>0){text('!',x,y-163,23,'#ffba64','center');rect(x-20,y-140,40,3,'#421a11');rect(x-20,y-140,40*(1-entity.wind/.55),3,'#f6a64a');}else if(entity.hp<entity.maxHp){rect(x-23,y-149,46,4,'#171a12');rect(x-23,y-149,46*entity.hp/entity.maxHp,4,entity.boss?'#e7bb65':'#d96b4a');}}
}
function titleDraw(){backdrop(0,0);ctx.fillStyle='#03070a40';ctx.fillRect(0,0,960,540);actor({crew:3,x:840,y:420,z:0,face:-1,hp:100},false,1.16);actor({crew:2,x:670,y:423,z:0,face:-1,hp:100},false,1.25);actor({crew:0,x:785,y:489,z:0,face:-1,hp:100},false,1.8);actor({crew:1,x:594,y:492,z:0,face:1,hp:100},false,1.65);rect(741,29,190,31,'#0c120fbd');text('01 / SATRIALE’S',836,40,10,'#e7cc91','center');text('THE WHOLE FAMILY IS HERE.',731,518,8,'#d8c6a2','center');}
function drawHUD(){const g=game;g.players.forEach((p,i)=>{const x=i===0?23:653,c=CREW[p.crew];rect(x-7,17,298,83,'#07100de0');rect(x-7,17,3,83,c.color);text('P'+(i+1)+' / '+c.name,x+4,25,14,c.color);text('LIVES '+Math.max(0,p.lives),x+274,28,10,'#c0bda5','right');rect(x+4,47,270,15,'#452e27');rect(x+4,47,270*p.hp/p.maxHp,15,c.color);rect(x+4,47,270*p.hp/p.maxHp,3,'#ffffff44');text(Math.ceil(p.hp)+' / '+p.maxHp,x+138,50,9,'#172014','center');rect(x+4,69,270,5,'#303b32');rect(x+4,69,270*p.energy/100,5,'#8ab9ba');text(p.energy>=35?c.special+' READY':'SPECIAL RECHARGING',x+4,82,8,p.energy>=35?'#a8d1cc':'#707e75');if(p.hp<=0)text(p.lives>0?'BACK IN A MOMENT…':'OUT OF ACTION',x+139,112,11,'#e7bb65','center');if(p.combo>=2&&p.comboTime>0){text(p.combo+' HITS',x+8,123,25,c.color);if(p.combo>=5)text(p.combo>=10?'FAMILY LEGEND':'MAKING A POINT',x+8,153,8,'#f2dab1');}});
 text('SCORE',480,20,8,'#b2b89e','center');text(String(Math.floor(g.score)).padStart(6,'0'),480,34,21,'#e8c27b','center');text(`${g.stage+1}—${g.sector+1} / ${STAGES[g.stage].name}`,480,65,9,'#cfcec0','center');if(g.players.length===1){text('SOLO RUN',935,28,10,'#d8b773','right');text(STAGES[g.stage].track.toUpperCase(),935,45,8,'#aeb5a7','right');}
 const boss=g.enemies.find(e=>e.boss&&e.hp>0);if(boss){rect(320,105,320,26,'#080d0bda');text(boss.name,480,109,9,'#e7bb65','center');rect(325,123,310,4,'#3f2c23');rect(325,123,310*boss.hp/boss.maxHp,4,'#dc6a47');}
 if(g.clear){const pulse=reducedMotion?1:.65+Math.sin(clock*7)*.35;ctx.globalAlpha=pulse;text('GO →',915,270,26,'#f8d481','right');ctx.globalAlpha=1;text('NEXT BLOCK',915,302,8,'#ecd7ad','right');}
 if(g.banner>0){const opacity=Math.min(1,g.banner,2.5-g.banner+.15);ctx.globalAlpha=opacity;rect(280,183,400,83,'#090e0dd9');text('NEIGHBORHOOD '+(g.stage+1)+' · BLOCK '+(g.sector+1),480,196,10,'#d6b678','center');text(STAGES[g.stage].name,480,215,34,'#efe6ca','center','Impact');ctx.globalAlpha=1;}
 if(toastTime>0){ctx.globalAlpha=Math.min(1,toastTime);const tw=Math.min(900,ctx.measureText(toast).width+40);rect(480-tw/2,338,tw,25,'#08100ee6');text(toast,480,346,10,'#edcd8d','center');ctx.globalAlpha=1;}
}
function drawProjectile(p){const x=p.x-game.camera,y=p.y-p.z;ctx.save();ctx.translate(x,y);ctx.rotate(p.angle);if(p.kind==='phone'){rect(-7,-17,14,34,'#aebeb3');rect(-5,-14,10,9,'#193936');rect(1,-25,3,10,'#273731');for(let r=0;r<3;r++)for(let c=0;c<3;c++)rect(-4+c*3,-1+r*4,2,2,'#4a6257');rect(-4,13,8,2,'#45554b');}else{ctx.fillStyle='#191b1c';ctx.beginPath();ctx.arc(0,0,14,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#a3a39a';ctx.lineWidth=3;ctx.stroke();rect(11,-3,23,6,'#7e7662');}ctx.restore();}
function drawGame(){ctx.save();if(game.shake&&!reducedMotion)ctx.translate(Math.sin(clock*121)*game.shake,Math.cos(clock*105)*game.shake*.4);backdrop(game.stage,game.camera);for(const p of game.pickups){const x=p.x-game.camera,y=p.y+Math.sin(clock*4+p.bob)*3;if(p.kind==='cash'){rect(x-11,y-8,22,14,'#c2b18a');ctx.strokeStyle='#635d45';ctx.beginPath();ctx.moveTo(x-10,y-7);ctx.lineTo(x,y);ctx.lineTo(x+10,y-7);ctx.stroke();}else{rect(x-14,y-7,28,9,'#dba864');rect(x-12,y+2,24,3,'#699044');rect(x-12,y+5,24,3,'#c67764');rect(x-14,y+8,28,4,'#dba864');}text(p.kind==='cash'?'$':'HP',x,y-20,8,'#e8d293','center');}
 const entities=[...game.players.map(p=>({p,enemy:false})),...game.enemies.map(p=>({p,enemy:true}))].sort((a,b)=>a.p.y-b.p.y);for(const e of entities)actor(e.p,e.enemy,e.p.boss?1.15:1,game.camera);for(const p of game.projectiles)drawProjectile(p);for(const p of game.particles)rect(p.x-game.camera,p.y,3,3,p.color);ctx.restore();drawHUD();}
function events(){for(const e of game.events.splice(0)){audio.effect(e.type);if(e.type==='special'){toast=e.name==='SOME PULP'?'“SOME PULP!”  — CARMELA':e.name;toastTime=1.8;}if(e.type==='pickup'){toast=e.name;toastTime=1;}if(e.type==='empty'){toast='BUILD YOUR METER — KEEP SWINGING';toastTime=1.4;}if(e.type==='stageclear'){saveScore();setOverlay('stageclear','BUSINESS HANDLED.',`${STAGES[game.stage].name} is clear. Next stop: ${STAGES[game.stage+1].name}. Health and special meters restored for the next neighborhood.`,'NEXT NEIGHBORHOOD','NEIGHBORHOOD COMPLETE');}if(e.type==='gameover'){saveScore();setOverlay('gameover','WHADDAYA GONNA DO?',`Score ${Math.floor(game.score).toLocaleString()} · ${game.kills} knockouts. ${game.continues} shared continues remaining.`,game.continues?'CONTINUE · '+game.continues+' LEFT':'','GAME OVER');}if(e.type==='victory'){saveScore();setOverlay('victory','THIS THING OF OURS.',`All three neighborhoods settled. ${game.kills} knockouts. Score: ${Math.floor(game.score).toLocaleString()}. The family is back in business.`, 'PLAY AGAIN','THE END · THANKS FOR PLAYING');}}}
function frame(t){const dt=Math.min(.035,(t-lastTime)/1000||.016);lastTime=t;clock+=dt;const input=inputs();if(game&&!paused&&!$('help-dialog').open){game.update(dt,input);events();toastTime=Math.max(0,toastTime-dt);}if(ready){ctx.imageSmoothingEnabled=false;if(game)drawGame();else titleDraw();}else{rect(0,0,960,540,'#0b100d');text('WAKING UP THE NEIGHBORHOOD…',480,420,12,'#c9ac70','center');}requestAnimationFrame(frame);}
// Read-only inspection for browser QA and accessibility tooling.
globalThis.arcadeState=()=>game?{...game.snapshot(),paused,audio:audio.enabled}:({phase:'selection',selected:selected.map(i=>padNames[i]),ready});
buildRoster();loadAssets();requestAnimationFrame(frame);
